import Distribution from "./distribution.vue";
import expandRow from "./tableExpand.vue";
import {
  orderList,
  getOrdeDatas,
  getDataInfo,
  getRefundFrom,
  getnoRefund,
  refundIntegral,
  getDistribution,
  writeUpdate,
  storeOrderApi,
  handBatchDelivery,
  putWrite,
  exportExpressList,
  remindOrder,
  putOpenRefund,
  orderWriteForm,
} from "@/api/order";
import { erpConfig } from "@/api/erp";
import { mapState, mapMutations } from "vuex";
import editFrom from "../../../../components/from/from";
import detailsFrom from "../handle/orderDetails";
import orderRemark from "../handle/orderRemark";
import orderRecord from "../handle/orderRecord";
import orderSend from "../handle/orderSend";
import userDetails from "@/pages/user/list/handle/userDetails";
import autoSend from "../handle/autoSend";
import queueList from "../handle/queueList";
import orderWriteOff from "./orderWriteOff";
import Setting from "@/setting";
import util from "@/libs/util";
import exportExcel from "@/utils/newToExcel.js";
import printJS from "print-js";

export default {
  name: "table_list",
  components: {
    expandRow,
    editFrom,
    detailsFrom,
    orderRemark,
    orderRecord,
    orderSend,
    userDetails,
    Distribution,
    autoSend,
    queueList,
    orderWriteOff,
  },
  props: ["where", "currentTab"],
  data() {
    const codeNum = (rule, value, callback) => {
      if (!value) {
        return callback(new Error("请填写核销码"));
      }
      // 模拟异步验证效果
      if (!Number.isInteger(value)) {
        callback(new Error("请填写12位数字"));
      } else {
        // const reg = /[0-9]{12}/;
        const reg = /\b\d{12}\b/;
        if (!reg.test(value)) {
          callback(new Error("请填写12位数字"));
        } else {
          callback();
        }
      }
    };
    return {
      openErp: false,
      distshow: false, //分配的弹窗
      delfromData: {},
      modal: false,
      orderList: [],
      pay_type: "",
      orderCards: [],
      loading: false,
      orderId: 0,
      orderNumId: "",
      page: {
        total: 0, // 总条数
        pageNum: 1, // 当前页
        pageSize: 10, // 每页显示条数
      },
      data: [],
      FromData: null,
      orderDatalist: null,
      modalTitleSs: "",
      isDelIdList: [],
      display: "none",
      autoDisabled: false,
      status: 0, //发货状态判断
      // isAll: -1,
      rowActive: {},
      tablists: {},
      selectArr: [],
      exportList: [
        {
          name: "1",
          label: "导出发货单",
        },
        {
          name: "0",
          label: "导出订单",
        },
      ],
      exportListOn: 0,
      manualModal: false,
      uploadAction: `${Setting.apiBaseURL}/file/upload/1`,
      uploadHeaders: {},
      autoModal: false,
      isShow: false,
      recordModal: false,
      sendOutValue: "",
      fileList: [],
      file: "",
      modals2: false,
      writeOffRules: {
        code: [{ validator: codeNum, trigger: "blur", required: true }],
      },
      writeOffFrom: {
        code: "",
        confirm: 0,
      },
      orderConNum: 0,
      orderConId: 0,
      formSelection: [],
      checkBox: false,
      ids: [],
      isAll: 0,
      checkUidList: [],
      refundModal: false,
      refundColumns: [
        {
          type: "selection",
          width: 60,
          align: "center",
        },
        {
          title: "商品信息",
          width: 210,
          slot: "product",
        },
        {
          title: "规格",
          render: (h, params) => {
            return h("div", params.row.productInfo.attrInfo.suk);
          },
        },
        {
          title: "售价",
          render: (h, params) => {
            return h("div", params.row.productInfo.attrInfo.price);
          },
        },
        {
          title: "优惠价",
          key: "refundPrice",
        },
        {
          title: "总数",
          key: "cart_num",
        },
        {
          title: "退款数量",
          slot: "action",
          width: 160,
        },
      ],
      refundProduct: [],
      refundSelection: [],
      refundMoney: 0,
      is_split_order: 0,
      orderDataStatus: "",
    };
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    ...mapState("admin/order", [
      "orderPayType",
      "orderStatus",
      "orderTime",
      "orderNum",
      "fieldKey",
      "orderType",
      "orderChartType",
      "supplier_id",
      "store_id",
      "type_id",
    ]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
    refundProductNum() {
      return this.refundProduct.reduce(
        (total, { refundNum }) => total + refundNum,
        0
      );
    },
  },
  mounted() {},
  created() {
    this.getList();
    this.getToken();
    this.getErpConfig();
  },
  watch: {
    currentTab() {
      this.onClickTab();
    },
    orderType: function() {
      this.page.pageNum = 1;
      this.getList();
    },
    orderList: {
      deep: true,
      handler(value) {
        value.forEach((item) => {
          this.formSelection.forEach((itm) => {
            if (itm.id === item.id) {
              item.checkBox = true;
            }
          });
        });
        const arr = this.orderList.filter((item) => item.checkBox);
        if (this.orderList.length) {
          this.checkBox = this.orderList.length === arr.length;
        } else {
          this.checkBox = false;
        }
      },
    },
    refundSelection: {
      handler(value) {
        console.log(value);
        this.refundMoney = value.reduce((total, { refundPrice, refundNum }) => {
          return this.$computes.Add(
            total,
            this.$computes.Mul(refundPrice, refundNum)
          );
        }, 0);
      },
      deep: true,
    },
    is_split_order(value) {
      this.$nextTick(() => {
        this.$refs.refundTable.selectAll(!!value);
      });
    },
    refundMoney(value) {
      this.$nextTick(() => {
        if (typeof value != "number") {
          return;
        }
        if (parseFloat(value) == parseInt(value)) {
          return;
        }
        if (value.toString().length - (value.toString().indexOf(".") + 1) > 2) {
          this.refundMoney = Number(value.toFixed(2));
        }
      });
    },
  },
  methods: {
    ...mapMutations("admin/order", [
      "getIsDel",
      "getisDelIdListl",
      "onChangeTabs",
      "getStore_id",
      "getSupplier_id",
    ]),
    visibleChange(visible) {
      this.is_split_order = 0;
      if (!visible) {
        this.refundSelection = [];
      }
    },
    cancelRefundModal() {
      this.refundModal = false;
    },
    putOpenRefund() {
      let data = {
        id: this.orderId,
        refund_price: this.refundMoney,
        type: 1,
        is_split_order: this.is_split_order,
      };
      if (this.is_split_order) {
        if (!this.refundSelection.length) {
          return this.$Message.error("请选择需要退款的商品");
        }
        data.cart_ids = this.refundSelection.map(({ id, refundNum }) => ({
          cart_id: id,
          cart_num: refundNum,
        }));
      }
      putOpenRefund(data)
        .then((res) => {
          this.$Message.success(res.msg);
          this.refundModal = false;
          this.getData(this.orderDatalist.orderInfo.id);
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    refundSelectionChange(selection) {
      this.refundSelection = selection;
    },
    refundNumChange({ id, refundNum }) {
      let result = this.refundSelection.find((item) => item.id === id);
      if (result) {
        result.refundNum = refundNum;
      }
    },
    checkboxItem(e) {
      let id = parseInt(e.rowid);
      let index = this.checkUidList.indexOf(id);
      if (index !== -1) {
        this.checkUidList = this.checkUidList.filter((item) => item !== id);
      } else {
        this.checkUidList.push(id);
      }
    },
    checkboxAll() {
      // 获取选中当前值
      let obj2 = this.$refs.xTable.getCheckboxRecords(true);
      // 获取之前选中值
      let obj = this.$refs.xTable.getCheckboxReserveRecords(true);
      if (
        this.isAll == 0 &&
        this.checkUidList.length <= obj.length &&
        !this.isCheckBox
      ) {
        obj = [];
      }
      obj = obj.concat(obj2);
      let ids = [];
      obj.forEach((item) => {
        ids.push(parseInt(item.id));
      });
      this.checkUidList = ids;
      if (!obj2.length) {
        this.isCheckBox = false;
      }
    },
    allPages(e) {
      this.isAll = e;
      if (e == 0) {
        this.$refs.xTable.toggleAllCheckboxRow();
        // this.checkboxAll();
      } else {
        if (!this.isCheckBox) {
          this.$refs.xTable.setAllCheckboxRow(true);
          this.isCheckBox = true;
          this.isAll = 1;
        } else {
          this.$refs.xTable.setAllCheckboxRow(false);
          this.isCheckBox = false;
          this.isAll = 0;
        }
        this.checkUidList = [];
      }
    },
    //erp配置
    getErpConfig() {
      erpConfig()
        .then((res) => {
          this.openErp = res.data.open_erp;
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    printOreder() {
      if (
        this.checkUidList.length > 10 ||
        (this.isAll == 1 && this.page.total > 10)
      ) {
        return this.$Message.error("最多批量打印10个订单");
      }
      let ids = [];
      if (this.isAll == 1 && this.page.total <= 10) {
        this.orderList.forEach((item) => {
          ids.push(parseInt(item.id));
        });
      }
      let pathInfo = this.$router.resolve({
        path: "/admin/supplier/order/distribution",
        query: {
          id: this.isAll == 1 ? ids.join(",") : this.checkUidList.join(","),
          status: 2,
        },
      });
      window.open(pathInfo.href, "_blank");
    },

    delAll() {
      if (this.checkUidList.length === 0 && this.isAll == 0) {
        return this.$Message.error("请先选择删除的订单！");
      }
      let idss = {
        all: this.isAll,
        ids: this.checkUidList,
      };
      let delfromData = {
        title: "删除订单",
        url: `/order/dels`,
        method: "post",
        ids: idss,
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.checkUidList = [];
          this.getList();
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },

    onAuto() {
      this.$refs.sends.modals = true;
      this.$refs.sends.getList();
      this.$refs.sends.getDeliveryList();
    },
    // 提醒发货
    btnClick(row) {
      let data = {
        supplier_id: row.supplier_id,
        id: row.id,
      };
      remindOrder(data)
        .then(async (res) => {
          this.$Message.success(res.msg);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },

    queuemModal() {
      this.$refs.queue.modal = true;
    },

    // 下载物流公司对照表
    async getExpressList() {
      let [th, filekey, data, fileName] = [[], [], [], ""];
      let lebData = await this.getExcelData();
      if (!fileName) fileName = lebData.filename;
      if (!filekey.length) {
        filekey = lebData.filekey;
      }
      if (!th.length) th = lebData.header;
      data = lebData.export;
      exportExcel(th, filekey, fileName, data);
    },

    getExcelData() {
      return new Promise((resolve, reject) => {
        exportExpressList().then((res) => {
          return resolve(res.data);
        });
      });
    },

    // 订单核销
    writeOff() {
      this.modals2 = true;
    },

    // 验证
    search(name) {
      this.$refs[name].validate((valid) => {
        if (valid) {
          this.writeOffFrom.confirm = 0;
          putWrite(this.writeOffFrom)
            .then(async (res) => {
              if (res.status === 200) {
                // this.orderInfo = res.data;
                this.$Message.success(res.msg);
              } else {
                this.$Message.error(res.msg);
              }
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
        } else {
          this.$Message.error("请填写正确的核销码");
        }
      });
    },

    // 订单核销
    ok() {
      if (!this.writeOffFrom.code) {
        this.$Message.warning("请先验证订单！");
      } else {
        this.writeOffFrom.confirm = 1;
        putWrite(this.writeOffFrom)
          .then(async (res) => {
            if (res.status === 200) {
              this.$Message.success(res.msg);
              this.modals2 = false;
              this.getList();
              this.$refs[name].resetFields();
            } else {
              this.$Message.error(res.msg);
            }
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
      }
    },

    del(name) {
      // this.orderInfo = ''
      this.modals2 = false;
      this.writeOffFrom.confirm = 0;
      this.$refs[name].resetFields();
    },

    // 上传头部token
    getToken() {
      this.uploadHeaders["Authori-zation"] =
        "Bearer " + util.cookies.get("token");
    },

    // 上传成功
    uploadSuccess(res, file, fileList) {
      if (res.status === 200) {
        this.$Message.success(res.msg);
        this.file = res.data.src;
        this.fileList = fileList;
      } else {
        this.$Message.error(res.msg);
      }
    },

    //移除文件
    removeFile(file, fileList) {
      this.file = "";
      this.fileList = fileList;
    },

    // 手动批量发货-确定
    manualModalOk() {
      this.$refs.upload.clearFiles();
      handBatchDelivery({ file: this.file })
        .then((res) => {
          this.$Message.success(res.msg);
          this.fileList = [];
        })
        .catch((err) => {
          this.$Message.error(err.msg);
          this.fileList = [];
        });
    },

    // 手动批量发货-取消
    manualModalCancel() {
      this.fileList = [];
      this.$refs.upload.clearFiles();
    },

    getTabs() {
      this.spinShow = true;
      this.$store
        .dispatch("admin/order/getOrderTabs", {
          status: this.orderStatus,
          pay_type: this.orderPayType,
          data: this.orderTime,
          real_name: this.orderNum,
          field_key: this.fieldKey,
          type: this.type_id,
          plat_type: this.currentTab,
          store_id: this.store_id,
          supplier_id: this.supplier_id,
        })
        .then((res) => {
          this.tablists = res.data;
          // this.onChangeChart(this.tablists)
          this.spinShow = false;
        })
        .catch((res) => {
          this.spinShow = false;
          this.$Message.error(res.msg);
        });
    },
    onClickTab() {
      this.onChangeTabs(this.currentTab);
      this.isAll = 0;
      this.isCheckBox = false;
      this.$refs.xTable.setAllCheckboxRow(false);
      this.checkUidList = [];
      if (this.currentTab == 1) {
        this.getSupplier_id("");
      }
      if (this.currentTab == 2) {
        this.getStore_id("");
      }
      // this.getList()
      this.$store.dispatch("admin/order/getOrderTabs", {
        type: this.currentTab,
      });
    },
    selectChange2() {
      this.$emit("selectChange2", this.orderDataStatus);
    },
    closeDetail() {
      this.$refs.detailss.modals = false;
    },
    distribution(row) {
      this.$refs.distshow.modals = true;
      this.$refs.distshow.formValidate.keywords = "";
      this.$refs.distshow.getList(row.id);
    },
    showUserInfo(row) {
      this.$refs.userDetails.modals = true;
      this.$refs.userDetails.activeName = "info";
      this.$refs.userDetails.getDetails(row.uid);
    },

    //修改增加打印方法
    printImg(url) {
      printJS({
        printable: url,
        type: "image",
        documentTitle: "快递信息",
        style: `img{
	      width: 100%;
	      height: 476px;
	    }`,
      });
    },

    // 操作
    changeMenu(row, name, num) {
      this.orderId = row.id;
      this.orderConId = row.pid > 0 ? row.pid : row.id;
      this.orderConNum = num;
      switch (name) {
        case "1":
          this.delfromData = {
            title: "修改立即支付",
            url: `/order/pay_offline/${row.id}`,
            method: "post",
            ids: "",
          };
          this.$modalSure(this.delfromData)
            .then((res) => {
              this.$Message.success(res.msg);
              this.$emit("changeGetTabs");
              this.getData(row.id, 1);
              this.getList();
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
          // this.modalTitleSs = '修改立即支付';
          break;
        case "2":
          this.rowActive = row;
          this.getData(row.id);
          break;
        case "3":
          this.$refs.record.modals = true;
          this.$refs.record.getList(row.id);
          break;
        case "4":
          this.$refs.remarks.formValidate.remark = row.remark;
          this.$refs.remarks.modals = true;
          break;
        case "5":
          this.getOnlyRefundData(row.id, row.refund_type, row);
          break;
        case "55":
          this.getRefundData(row.id, row.refund_type);
          break;
        case "6":
          this.getRefundIntegral(row.id);
          break;
        case "7":
          this.getNoRefundData(row.id);
          break;
        case "8":
          if (row.refund.length)
            return this.$Message.error("该订单有售后处理中，请先处理售后申请");
          this.delfromData = {
            title: "修改确认收货",
            url: `/order/take/${row.id}`,
            method: "put",
            ids: "",
          };
          this.$modalSure(this.delfromData)
            .then((res) => {
              this.$Message.success(res.msg);
              this.$emit("changeGetTabs");
              this.getList();
              if (num) {
                this.$refs.detailss.getSplitOrder(row.pid);
              } else {
                this.getData(row.id, 1);
              }
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
          // this.modalTitleSs = '修改确认收货';
          break;
        case "10":
          this.delfromData = {
            title: "立即打印订单",
            info: "您确认打印此订单吗?",
            url: `/order/print/${row.id}`,
            method: "get",
            ids: "",
          };
          this.$modalSure(this.delfromData)
            .then((res) => {
              this.$Message.success(res.msg);
              this.$emit("changeGetTabs");
              this.getList();
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
          break;
        case "11":
          this.delfromData = {
            title: "立即打印电子面单",
            info: "您确认打印此电子面单吗?",
            url: `/order/order_dump/${row.id}`,
            method: "get",
            ids: "",
          };
          this.$modalSure(this.delfromData)
            .then((res) => {
              this.$Message.success(res.msg);
              this.getList();
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
          break;
        case "12":
          let pathInfo = this.$router.resolve({
            path: "/admin/supplier/order/distribution",
            query: {
              id: row.id,
              status: 2,
            },
          });
          window.open(pathInfo.href, "_blank");
          break;
        case "13":
          this.printImg(row.kuaidi_label);
          break;
        default:
          this.delfromData = {
            title: "删除订单",
            url: `/order/del/${row.id}`,
            method: "DELETE",
            ids: "",
          };
          // this.modalTitleSs = '删除订单';
          this.delOrder(row, this.delfromData);
      }
    },

    // 立即支付 /确认收货//删除单条订单
    submitModel() {
      this.getList();
    },
    pageChange(index) {
      this.page.pageNum = index;
      this.getList();
    },
    limitChange(limit) {
      this.page.pageSize = limit;
      this.getList();
    },

    // 订单列表
    getList(res) {
      if (res == 1) {
        this.isAll = 0;
        this.$refs.xTable.setAllCheckboxRow(false);
        this.checkUidList = [];
      }
      this.page.pageNum = res === 1 ? 1 : this.page.pageNum;
      this.loading = true;
      orderList({
        page: this.page.pageNum,
        limit: this.page.pageSize,
        status: this.orderStatus,
        pay_type: this.orderPayType,
        data: this.orderTime,
        real_name: this.orderNum,
        field_key: this.fieldKey,
        type: this.type_id,
        plat_type: this.currentTab,
        store_id: this.store_id,
        supplier_id: this.supplier_id,
      })
        .then(async (res) => {
          let { count, data, stat } = res.data;
          data.forEach((item) => {
            item.checkBox = this.isAll == 1;
            if (item.id == this.orderId) {
              this.rowActive = item;
            }
          });
          this.orderList = data;
          this.orderCards = stat;
          this.page.total = count;
          this.$emit("on-changeCards", stat);
          this.loading = false;
          this.getTabs();
          this.$nextTick(function() {
            if (this.isAll == 1) {
              if (this.isCheckBox) {
                this.$refs.xTable.setAllCheckboxRow(true);
              } else {
                this.$refs.xTable.setAllCheckboxRow(false);
              }
            } else {
              let obj = this.$refs.xTable.getCheckboxReserveRecords(true);
              if (
                !this.checkUidList.length ||
                this.checkUidList.length <= obj.length
              ) {
                this.$refs.xTable.setAllCheckboxRow(false);
              }
            }
          });
        })
        .catch((res) => {
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },

    // 编辑
    edit(row) {
      this.getOrderData(row.id);
    },
    splitOrderDetail(row) {
      this.$router.push({
        path: "split_list",
        query: {
          id: row.id,
          orderChartType: this.orderStatus,
        },
      });
    },

    // 删除单条订单
    delOrder(row, data) {
      if (row.is_del === 1) {
        this.$modalSure(data)
          .then((res) => {
            this.$Message.success(res.msg);
            this.getList();
            this.$refs.detailss.modals = false;
            this.$emit("changeGetTabs");
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
      } else {
        const title = "错误！";
        const content =
          "<p>您选择的的订单存在用户未删除的订单，无法删除用户未删除的订单！</p>";
        this.$Modal.error({
          title: title,
          content: content,
        });
      }
    },

    // 获取编辑表单数据
    getOrderData(id) {
      getOrdeDatas(id)
        .then(async (res) => {
          if (res.data.status === false) {
            return this.$authLapse(res.data);
          }
          this.$authLapse(res.data);
          this.FromData = res.data;
          this.$refs.edits.modals = true;
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },

    // 获取详情表单数据
    getData(id, type) {
      // this.$refs.detailss.modals = true;
      getDataInfo(id)
        .then(async (res) => {
          if (!type) {
            this.$refs.detailss.modals = true;
          }
          this.$refs.detailss.activeName = "detail";
          this.orderDatalist = res.data;
          if (this.orderDatalist.orderInfo.refund_reason_wap_img) {
            try {
              this.orderDatalist.orderInfo.refund_reason_wap_img = JSON.parse(
                this.orderDatalist.orderInfo.refund_reason_wap_img
              );
            } catch (e) {
              this.orderDatalist.orderInfo.refund_reason_wap_img = [];
            }
          }
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },

    // 修改成功
    submitFail(type) {
      this.status = 0;
      this.getList();
      if (this.orderConNum != 1) {
        this.getData(this.orderId, 1);
      } else {
        this.$refs.detailss.getSplitOrder(this.orderConId);
      }
      if (type) {
        this.$emit("changeGetTabs");
      }
    },

    // 仅退款
    getOnlyRefundData(id, refund_type, rowActive) {
      // this.$modalForm(getRefundFrom(id)).then(() => {
      //   this.getList()
      //   this.$emit('changeGetTabs')
      //   this.$refs.detailss.modals = false
      // })
      let _info = rowActive._info;
      let cart_info = Object.keys(_info)
        .map((key) => {
          return _info[key].cart_info;
        })
        .filter((value) => {
          return !value.is_gift;
        });
      cart_info.forEach((value) => {
        value.refundPrice = this.$computes.Div(
          value.refund_price,
          value.cart_num
        );
        value.refundNum = value.cart_num - value.refund_num;
        value._disabled = !value.refundNum;
      });
      this.refundProduct = cart_info;
      if (this.refundProductNum === 1) {
        this.refundSelection = cart_info;
      }
      this.refundModal = true;
    },

    // 退货退款
    getRefundData(id, refund_type) {
      this.delfromData = {
        title: "是否立即退货退款",
        url: `/refund/agree/${id}`,
        method: "get",
      };
      this.$modalSure(this.delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.getList();
          this.$emit("changeGetTabs");
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },

    // 获取退积分表单数据
    getRefundIntegral(id) {
      refundIntegral(id)
        .then(async (res) => {
          this.FromData = res.data;
          this.$refs.edits.modals = true;
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },

    // 不退款表单数据
    getNoRefundData(id) {
      this.$modalForm(getnoRefund(id)).then(() => {
        this.getList();
        this.$emit("changeGetTabs");
      });
    },

    // 发送货
    sendOrder(row, num) {
      if (row.is_stock_up == 1 && row.status == 0)
        return this.$Message.warning("商家寄件，等待平台返回快递单号");
      this.orderConId = row.pid;
      this.orderConNum = num;
      this.$store.commit("admin/order/setSplitOrder", row.total_num);
      this.$refs.send.modals = true;
      this.orderId = row.id;
      this.status = row._status;
      this.pay_type = row.pay_type;
      this.$refs.send.getList();
      this.$refs.send.getDeliveryList();
      this.$refs.send.getBusineseList();
      this.$nextTick((e) => {
        this.$refs.send.getCartInfo(row._status, row.id);
      });
    },

    // 配送信息表单数据
    delivery(row, num) {
      getDistribution(row.id)
        .then(async (res) => {
          this.orderConNum = num;
          this.orderConId = row.pid;
          this.FromData = res.data;
          this.$refs.edits.modals = true;
          if (num != 1) {
            this.getData(this.orderId, 1);
          }
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },

    // 订单导出
    change(status) {},
    async exports(value) {
      this.exportListOn = this.exportList.findIndex(
        (item) => item.name === value
      );
      let [th, filekey, data, fileName] = [[], [], [], ""];
      //   let fileName = "";
      let excelData = JSON.parse(JSON.stringify(this.where));
      excelData.page = 1;
      excelData.export_type = value;
      excelData.ids = this.checkUidList.join(",");
      for (let i = 0; i < excelData.page + 1; i++) {
        let lebData = await this.downOrderData(excelData);
        if (!fileName) fileName = lebData.filename;
        if (!filekey.length) {
          filekey = lebData.filekey;
        }
        if (!th.length) th = lebData.header;
        if (lebData.export.length) {
          data = data.concat(lebData.export);
          excelData.page++;
        } else {
          let result = [];
          for (let j = 0; j < data.length; j++) {
            let goodsList = data[j]["goods_name"].split("\n");
            for (let k = 0; k < goodsList.length; k++) {
              result.push({ ...data[j] });
              result[result.length - 1]["goods_name"] = goodsList[k];
              if (!k) {
                continue;
              }
              for (const key in result[result.length - 1]) {
                if (key === "goods_name") {
                  continue;
                }
                result[result.length - 1][key] = null;
              }
            }
          }
          exportExcel(th, filekey, fileName, result);
          return;
        }
      }
    },

    downOrderData(excelData) {
      return new Promise((resolve, reject) => {
        storeOrderApi(excelData).then((res) => {
          return resolve(res.data);
        });
      });
    },
    submitSuccess() {
      this.getList();
      if (this.$refs.detailss.modals) {
        this.getData(this.orderId, 1);
      }
    },
    // 单个核销
    singleWrite(row) {
      let self = this;
      this.$Modal.confirm({
        title: "提示",
        content: "确定要核销该订单吗？",
        cancelText: "取消",
        closable: true,
        maskClosable: true,
        onOk: function() {
          writeUpdate(row.order_id).then((res) => {
            self.$Message.success(res.msg);
            self.getList();
          });
        },
        onCancel: () => {},
      });
    },
    // 立即核销
    bindWrite(row) {
      if (row.total_num > 1) {
        this.orderNumId = row.order_id;
        this.$refs.writeOff.modals = true;
        this.$refs.writeOff.getWriteOff({ oid: row.id });
      } else {
        if (row.product_type == 4) {
          this.$modalForm(orderWriteForm(row.id)).then((res) => {
            this.$Message.success(res.msg);
            this.getList();
            this.getChart();
            if (this.$refs.detailss.modals) {
              this.getData(this.orderId, 1);
            }
          });
        } else {
          this.singleWrite(row);
        }
      }
    },
  },
};
